insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('como-influye-el-entorno-de-un-barrio-en-el-bienestar-de-quienes-viven-ahi','ciudades',array['salud','sociedad']::text[],'¿Cómo influye el entorno de un barrio en el bienestar de quienes viven ahí?','Observa un barrio o una zona de tu centro de estudios y descubre cómo su diseño, sus espacios y su ambiente se relacionan con la actividad física y con cómo se sienten las personas.','Investigación','~25 h',25,array['Espacio urbano','Bienestar']::text[],array['investigar','resolver']::text[],'propios',NULL,'arquitectura ingenieria civil psicologia trabajo social sociologia ingenieria ambiental estadistica medicina observacion de campo. encuestas breves. analisis basico de datos. mapeo. fichas de observacion en papel o en el celular. hoja de calculo. un mapa digital o un plano dibujado.',$g00sld${"id": "como-influye-el-entorno-de-un-barrio-en-el-bienestar-de-quienes-viven-ahi", "area": "ciudades", "areas2": ["salud", "sociedad"], "titulo": "¿Cómo influye el entorno de un barrio en el bienestar de quienes viven ahí?", "resumen": "Observa un barrio o una zona de tu centro de estudios y descubre cómo su diseño, sus espacios y su ambiente se relacionan con la actividad física y con cómo se sienten las personas.", "tipo": "Investigación", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Espacio urbano", "Bienestar"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "propios: puedes usar tus propias mediciones y las de personas cercanas que acepten participar, sin datos médicos ni diagnósticos.", "carreras": ["Arquitectura", "Ingeniería Civil", "Psicología", "Trabajo Social", "Sociología", "Ingeniería Ambiental", "Estadística", "Medicina"], "problema": ["El lugar donde vivimos y estudiamos influye en cuánto caminamos, cuánto descansamos y cómo nos sentimos, pero casi nunca se mira con esa lente: se habla de la salud de las personas y del diseño de los espacios por separado.", "Dos calles parecidas pueden dar experiencias muy distintas: una con sombra, bancas y gente se camina con gusto; otra con ruido, huecos y sin dónde sentarse se evita. Esa diferencia casi nunca está registrada."], "desarrollar": ["Elige dos o tres espacios de tu zona (una calle, un parque, el patio de una institución) y anota con una ficha sencilla qué ofrece cada uno: sombra, lugares para sentarse, seguridad aparente, ruido, personas que lo usan.", "Pregunta de forma anónima a unas pocas personas cómo se sienten en cada lugar y cuánto lo usan, compara sus respuestas con tus fichas y concluye qué características del espacio parecen ayudar más al bienestar y al movimiento."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara cómo viven el mismo espacio personas de distintas edades, como estudiantes, niños y adultos mayores."}, {"titulo": "Otro formato", "aporta": "resume los resultados en un mapa con colores que muestre qué zonas invitan más a quedarse y cuáles menos."}, {"titulo": "Un paso más", "aporta": "propón tres cambios sencillos para uno de los espacios y explica qué efecto esperarías."}], "objetivos": ["Describir un espacio con una ficha de observación.", "Recoger opiniones de forma anónima y ordenada.", "Relacionar características del espacio con el bienestar y el movimiento.", "Proponer mejoras sencillas."], "habilidades": ["Observación de campo.", "Encuestas breves.", "Análisis básico de datos.", "Mapeo."], "herramientas": ["Fichas de observación en papel o en el celular.", "Hoja de cálculo.", "Un mapa digital o un plano dibujado."], "lineamientos": ["Pide permiso antes de preguntar y no registres nombres ni fotografíes a personas: trabaja con respuestas anónimas.", "No concluyas que un espacio «causa» bienestar o malestar: son relaciones que observas, no pruebas."], "otroSector": "El mismo método sirve para analizar una oficina, una escuela, un centro comercial o un hospital."}$g00sld$::jsonb,7),
('un-mapa-de-lugares-para-caminar-y-hacer-ejercicio-cerca-de-ti','ciudades',array['salud','tecnologia']::text[],'Un mapa de lugares para caminar y hacer ejercicio cerca de ti','Reúne en un mapa los espacios públicos donde se puede caminar, correr, jugar o hacer ejercicio de forma libre y segura, con la información que alguien necesitaría para usarlos.','Guía','~15 h',15,array['Mapas','Actividad física']::text[],array['crear','resolver']::text[],'propios',NULL,'geografia arquitectura ingenieria civil ingenieria de sistemas ingenieria de software trabajo social medicina comunicaciones observacion de campo. mapeo. comunicacion clara. diseno de informacion. un mapa digital (como los que permiten crear mapas personalizados). hoja de calculo. un editor de paginas o de presentaciones.',$g01sld${"id": "un-mapa-de-lugares-para-caminar-y-hacer-ejercicio-cerca-de-ti", "area": "ciudades", "areas2": ["salud", "tecnologia"], "titulo": "Un mapa de lugares para caminar y hacer ejercicio cerca de ti", "resumen": "Reúne en un mapa los espacios públicos donde se puede caminar, correr, jugar o hacer ejercicio de forma libre y segura, con la información que alguien necesitaría para usarlos.", "tipo": "Guía", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Mapas", "Actividad física"], "intencion": ["crear", "resolver"], "datos": "propios", "datosTexto": "propios: puedes usar tus propias mediciones y las de personas cercanas que acepten participar, sin datos médicos ni diagnósticos.", "carreras": ["Geografía", "Arquitectura", "Ingeniería Civil", "Ingeniería de Sistemas", "Ingeniería de Software", "Trabajo Social", "Medicina", "Comunicaciones"], "problema": ["Muchas personas quieren moverse más, pero no saben qué espacios tienen cerca ni si están abiertos, iluminados o son adecuados para ellas. La información existe, pero está dispersa o no está.", "Un parque puede estar cerca y no usarse porque no se sabe cómo llegar, a qué hora está abierto o qué se puede hacer ahí."], "desarrollar": ["Recorre o investiga unos diez espacios de tu zona y anota para cada uno qué se puede hacer, horarios, si hay iluminación, sombra, agua y baños, y a quién le resultaría cómodo.", "Muéstralos en un mapa digital o dibujado con una ficha corta por lugar, y pide a dos personas que lo usen para planear una salida y te digan qué faltó."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "adapta el mapa para personas mayores o con movilidad reducida, marcando pendientes, bancas y rutas planas."}, {"titulo": "Otro formato", "aporta": "conviértelo en una página web sencilla que se pueda abrir desde el celular."}, {"titulo": "Un paso más", "aporta": "agrega rutas de caminata de distinta duración con tiempos estimados."}], "objetivos": ["Identificar espacios disponibles para moverse.", "Describir cada espacio con datos útiles y verificables.", "Mostrarlos en un mapa claro.", "Comprobar que otra persona lo puede usar."], "habilidades": ["Observación de campo.", "Mapeo.", "Comunicación clara.", "Diseño de información."], "herramientas": ["Un mapa digital (como los que permiten crear mapas personalizados).", "Hoja de cálculo.", "Un editor de páginas o de presentaciones."], "lineamientos": ["Verifica horarios y condiciones antes de publicarlos y avisa que pueden cambiar. Evita marcar lugares peligrosos como si fueran seguros.", "No indiques rutinas de ejercicio ni recomendaciones médicas: el mapa informa dónde, no cómo entrenar."], "otroSector": "La misma idea sirve para mapear espacios de lectura, de descanso, de estudio o de juego infantil."}$g01sld$::jsonb,8),
('cuanto-ruido-hay-donde-estudias-y-descansas','ciudades',array['salud','ciencias']::text[],'¿Cuánto ruido hay donde estudias y descansas?','Mide de forma aproximada el ruido de tus lugares de estudio y descanso a distintas horas, y descubre qué momentos y qué fuentes más interfieren en la concentración y el descanso.','Análisis','~15 h',15,array['Ruido','Concentración']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria ambiental ingenieria fisica ingenieria civil arquitectura psicologia estadistica medicina ingenieria de sistemas medicion. analisis basico de datos. graficos. pensamiento critico. una aplicacion de medicion de sonido para el celular. hoja de calculo. un cuaderno de registro.',$g02sld${"id": "cuanto-ruido-hay-donde-estudias-y-descansas", "area": "ciudades", "areas2": ["salud", "ciencias"], "titulo": "¿Cuánto ruido hay donde estudias y descansas?", "resumen": "Mide de forma aproximada el ruido de tus lugares de estudio y descanso a distintas horas, y descubre qué momentos y qué fuentes más interfieren en la concentración y el descanso.", "tipo": "Análisis", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Ruido", "Concentración"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "propios: puedes usar tus propias mediciones y las de personas cercanas que acepten participar, sin datos médicos ni diagnósticos.", "carreras": ["Ingeniería Ambiental", "Ingeniería Física", "Ingeniería Civil", "Arquitectura", "Psicología", "Estadística", "Medicina", "Ingeniería de Sistemas"], "problema": ["El ruido se siente como una molestia normal, pero influye en cuánto nos concentramos, cuánto descansamos y cómo terminamos el día. Casi nadie lo mide, así que no se sabe cuándo ni dónde es más fuerte.", "Lo que cuenta no es solo el volumen: un ruido constante, uno repentino y uno que no controlamos se viven distinto."], "desarrollar": ["Durante una semana, mide el ruido con una aplicación de celular en tres o cuatro lugares y horarios fijos (tu casa, la biblioteca, el aula, la calle) y anota qué lo produce y cómo te sentiste al estudiar o descansar.", "Ordena los datos en una tabla y un gráfico, identifica los momentos y las fuentes más molestas y propón dos o tres ajustes, como cambiar de horario, de lugar o de ubicación en la habitación."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara tus mediciones con los niveles que recomiendan organismos de salud y ambiente."}, {"titulo": "Otro formato", "aporta": "haz un mapa de ruido del campus o de tu barrio con zonas de colores."}, {"titulo": "Un paso más", "aporta": "diseña un «horario del silencio» para estudiar con menos interferencias."}], "objetivos": ["Medir el ruido de manera ordenada y comparable.", "Registrar cómo afecta la concentración y el descanso.", "Identificar fuentes y momentos más molestos.", "Proponer ajustes sencillos."], "habilidades": ["Medición.", "Análisis básico de datos.", "Gráficos.", "Pensamiento crítico."], "herramientas": ["Una aplicación de medición de sonido para el celular.", "Hoja de cálculo.", "Un cuaderno de registro."], "lineamientos": ["Las aplicaciones de celular dan valores aproximados: úsalos para comparar lugares y horas, no como mediciones oficiales, y explícalo en tu informe.", "No diagnostiques problemas de salud ni de audición: describe lo que mediste y cómo te sentiste."], "otroSector": "Sirve para analizar una oficina, un hospital, un taller, un restaurante o una escuela."}$g02sld$::jsonb,9),
('como-afecta-la-luz-de-un-espacio-a-como-te-sientes-en-el','ciudades',array['salud','arte']::text[],'¿Cómo afecta la luz de un espacio a cómo te sientes en él?','Compara cómo cambia la luz de un espacio a lo largo del día y cómo se relaciona con la comodidad, la concentración y el ánimo de quienes lo usan.','Investigación','~15 h',15,array['Iluminación','Bienestar']::text[],array['investigar','resolver']::text[],'propios',NULL,'arquitectura ingenieria civil diseno grafico psicologia ingenieria fisica estadistica medicina ingenieria ambiental medicion. observacion. analisis basico de datos. diseno de espacios. una aplicacion de medicion de luz del celular. hoja de calculo. una herramienta para dibujar planos.',$g03sld${"id": "como-afecta-la-luz-de-un-espacio-a-como-te-sientes-en-el", "area": "ciudades", "areas2": ["salud", "arte"], "titulo": "¿Cómo afecta la luz de un espacio a cómo te sientes en él?", "resumen": "Compara cómo cambia la luz de un espacio a lo largo del día y cómo se relaciona con la comodidad, la concentración y el ánimo de quienes lo usan.", "tipo": "Investigación", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Iluminación", "Bienestar"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "propios: puedes usar tus propias mediciones y las de personas cercanas que acepten participar, sin datos médicos ni diagnósticos.", "carreras": ["Arquitectura", "Ingeniería Civil", "Diseño Gráfico", "Psicología", "Ingeniería Física", "Estadística", "Medicina", "Ingeniería Ambiental"], "problema": ["La luz de un lugar casi siempre se decide por costo o por costumbre, pero afecta cuánto nos cansamos, cuán cómodos estamos y hasta cómo se ve lo que leemos.", "Dos aulas o dos habitaciones del mismo tamaño pueden sentirse muy distintas según de dónde entre la luz y qué tipo de lámparas tengan, y rara vez eso se compara."], "desarrollar": ["Elige dos o tres espacios (tu cuarto, un aula, una sala de estudio) y registra a distintas horas cuánta luz natural y artificial tienen, con una aplicación de medición de luz o con una escala simple que tú definas.", "Pide a algunas personas que respondan, de forma anónima, qué tan cómodas se sienten en cada lugar y hora, y cruza las respuestas con tus mediciones para ver qué patrones aparecen."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara el efecto de la luz cálida y la luz fría en la comodidad al leer."}, {"titulo": "Otro formato", "aporta": "dibuja un plano con las zonas más y menos iluminadas de un espacio."}, {"titulo": "Un paso más", "aporta": "propón un rediseño de la iluminación de un espacio con cambios de bajo costo."}], "objetivos": ["Medir la iluminación de un espacio a distintas horas.", "Recoger la comodidad percibida por las personas.", "Relacionar luz y comodidad con ejemplos concretos.", "Proponer una mejora de bajo costo."], "habilidades": ["Medición.", "Observación.", "Análisis básico de datos.", "Diseño de espacios."], "herramientas": ["Una aplicación de medición de luz del celular.", "Hoja de cálculo.", "Una herramienta para dibujar planos."], "lineamientos": ["Las mediciones con celular son aproximadas: úsalas para comparar, no como valores oficiales.", "No afirmes efectos médicos de la luz: habla de comodidad y percepción, que es lo que puedes observar."], "otroSector": "Sirve para analizar tiendas, oficinas, talleres, hospitales o aulas de colegio."}$g03sld$::jsonb,10),
('un-mapa-de-agua-para-beber-y-banos-publicos-en-tu-zona','ciudades',array['salud','sociedad']::text[],'Un mapa de agua para beber y baños públicos en tu zona','Ubica y describe los lugares de una zona donde se puede tomar agua y usar un baño, con la información práctica que alguien necesitaría al moverse por ahí.','Guía','~15 h',15,array['Mapas','Servicios básicos']::text[],array['crear','resolver']::text[],'propios',NULL,'geografia ingenieria civil ingenieria ambiental arquitectura trabajo social ingenieria de sistemas ingenieria de software medicina observacion de campo. mapeo. diseno de informacion. comunicacion clara. un mapa digital. hoja de calculo. un generador de codigos qr.',$g04sld${"id": "un-mapa-de-agua-para-beber-y-banos-publicos-en-tu-zona", "area": "ciudades", "areas2": ["salud", "sociedad"], "titulo": "Un mapa de agua para beber y baños públicos en tu zona", "resumen": "Ubica y describe los lugares de una zona donde se puede tomar agua y usar un baño, con la información práctica que alguien necesitaría al moverse por ahí.", "tipo": "Guía", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Mapas", "Servicios básicos"], "intencion": ["crear", "resolver"], "datos": "propios", "datosTexto": "propios: puedes usar tus propias mediciones y las de personas cercanas que acepten participar, sin datos médicos ni diagnósticos.", "carreras": ["Geografía", "Ingeniería Civil", "Ingeniería Ambiental", "Arquitectura", "Trabajo Social", "Ingeniería de Sistemas", "Ingeniería de Software", "Medicina"], "problema": ["Quien pasa el día fuera de casa, ya sea estudiando, trabajando o caminando, necesita beber agua y usar un baño, y muchas veces no sabe dónde hacerlo, a qué hora ni a qué costo.", "Esa falta de información afecta más a personas mayores, niños, personas con discapacidad o quienes pasan muchas horas en la calle, pero casi nunca está reunida en un solo lugar."], "desarrollar": ["Recorre una zona acotada, como tu centro de estudios y las calles de alrededor, y anota dónde hay bebederos, baños públicos o de acceso permitido, y para cada uno el horario, el costo y si es accesible.", "Ubícalos en un mapa con una ficha corta y pídele a alguien que use el mapa para planear un recorrido y te cuente qué faltó o qué no entendió."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "marca cuáles puntos son accesibles para sillas de ruedas o cochecitos."}, {"titulo": "Otro formato", "aporta": "conviértelo en una página web o en un código QR pegado en lugares clave."}, {"titulo": "Un paso más", "aporta": "propón dónde faltan puntos y cuántos harían falta para que la zona sea cómoda."}], "objetivos": ["Identificar puntos de agua y baños en una zona.", "Describir cada punto con datos útiles y verificables.", "Mostrarlos en un mapa claro.", "Detectar vacíos y proponer dónde faltan."], "habilidades": ["Observación de campo.", "Mapeo.", "Diseño de información.", "Comunicación clara."], "herramientas": ["Un mapa digital.", "Hoja de cálculo.", "Un generador de códigos QR."], "lineamientos": ["No afirmes que el agua es segura para beber si no hay una fuente oficial que lo diga: indica solo que existe el punto y cómo es.", "Pide permiso si vas a anotar datos de un local privado y respeta su horario y reglas de uso."], "otroSector": "La misma idea sirve para mapear enchufes, zonas de sombra, lugares para sentarse o servicios gratuitos."}$g04sld$::jsonb,11),
('que-necesita-una-persona-mayor-para-sentirse-segura-en-un-espacio-publico','ciudades',array['salud','sociedad']::text[],'¿Qué necesita una persona mayor para sentirse segura en un espacio público?','Descubre qué elementos de un espacio público hacen más fácil y seguro su uso para una persona mayor, y propón mejoras sencillas para uno que conozcas.','Plan','~20 h',20,array['Mayores','Espacio público']::text[],array['resolver','investigar']::text[],'propios',NULL,'arquitectura ingenieria civil trabajo social psicologia sociologia enfermeria administracion medicina entrevista y escucha. observacion. diseno de espacios. comunicacion. cuaderno de notas. una herramienta para dibujar planos. presentacion o afiche.',$g05sld${"id": "que-necesita-una-persona-mayor-para-sentirse-segura-en-un-espacio-publico", "area": "ciudades", "areas2": ["salud", "sociedad"], "titulo": "¿Qué necesita una persona mayor para sentirse segura en un espacio público?", "resumen": "Descubre qué elementos de un espacio público hacen más fácil y seguro su uso para una persona mayor, y propón mejoras sencillas para uno que conozcas.", "tipo": "Plan", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Mayores", "Espacio público"], "intencion": ["resolver", "investigar"], "datos": "propios", "datosTexto": "propios: puedes usar tus propias mediciones y las de personas cercanas que acepten participar, sin datos médicos ni diagnósticos.", "carreras": ["Arquitectura", "Ingeniería Civil", "Trabajo Social", "Psicología", "Sociología", "Enfermería", "Administración", "Medicina"], "problema": ["Los espacios públicos suelen diseñarse pensando en quien camina rápido y sin dificultad. Para una persona mayor, un desnivel, la falta de bancas o un cruce corto pueden convertir una salida simple en un riesgo o en una razón para quedarse en casa.", "Casi nunca se les pregunta qué necesitan, así que las mejoras se deciden sin su mirada."], "desarrollar": ["Recorre con permiso un espacio (un parque, una plaza, un paradero) junto a una persona mayor de confianza, o conversa con ella después, y anota qué le resulta fácil, difícil o inseguro, con fotos del lugar sin personas.", "Reúne lo que encuentres en una lista de problemas y propón tres mejoras sencillas, como bancas, mejor señalización o más tiempo para cruzar, con un dibujo o plano de cómo quedaría."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara lo que dicen personas mayores con lo que dicen quienes las acompañan o cuidan."}, {"titulo": "Otro formato", "aporta": "presenta tus propuestas en un afiche o una presentación para entregar a una junta vecinal o a la administración del lugar."}, {"titulo": "Un paso más", "aporta": "revisa si las mejoras sirven también a niños, embarazadas o personas con discapacidad."}], "objetivos": ["Escuchar las necesidades de una persona mayor en un espacio.", "Identificar obstáculos y riesgos concretos.", "Proponer mejoras sencillas.", "Comunicar las propuestas con claridad."], "habilidades": ["Entrevista y escucha.", "Observación.", "Diseño de espacios.", "Comunicación."], "herramientas": ["Cuaderno de notas.", "Una herramienta para dibujar planos.", "Presentación o afiche."], "lineamientos": ["Explica el propósito, pide permiso y respeta si la persona no quiere ser fotografiada o citada; no registres nombres ni datos médicos.", "No prometas que las mejoras se harán: preséntalas como propuestas basadas en lo que observaste."], "otroSector": "Sirve para mejorar la experiencia en un banco, un transporte, un hospital, una tienda o una oficina pública."}$g05sld$::jsonb,12),
('que-tan-preparada-esta-tu-zona-para-una-emergencia-de-salud','ciudades',array['salud','sociedad']::text[],'¿Qué tan preparada está tu zona para una emergencia de salud?','Revisa qué tendrían a mano una familia y un barrio ante una emergencia que afecte la salud (un sismo, una inundación o un corte prolongado de servicios) y prepara una guía de acción sencilla.','Plan','~20 h',20,array['Emergencias','Preparación']::text[],array['resolver','investigar']::text[],'publicos',NULL,'ingenieria civil ingenieria ambiental ingenieria industrial arquitectura trabajo social enfermeria medicina geografia investigacion de fuentes oficiales. mapeo. planificacion. redaccion clara. un mapa digital. hoja de calculo. un editor de documentos.',$g06sld${"id": "que-tan-preparada-esta-tu-zona-para-una-emergencia-de-salud", "area": "ciudades", "areas2": ["salud", "sociedad"], "titulo": "¿Qué tan preparada está tu zona para una emergencia de salud?", "resumen": "Revisa qué tendrían a mano una familia y un barrio ante una emergencia que afecte la salud (un sismo, una inundación o un corte prolongado de servicios) y prepara una guía de acción sencilla.", "tipo": "Plan", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Emergencias", "Preparación"], "intencion": ["resolver", "investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Ingeniería Civil", "Ingeniería Ambiental", "Ingeniería Industrial", "Arquitectura", "Trabajo Social", "Enfermería", "Medicina", "Geografía"], "problema": ["Cuando ocurre una emergencia, las necesidades de salud cambian: hay personas que dependen de medicamentos, de equipos eléctricos o de transporte, y los servicios pueden estar lejos o colapsados. Pocas familias y casi ningún barrio lo han pensado antes.", "Los planes de emergencia suelen hablar de evacuar y poco de cuidar la salud de quienes más lo necesitan, como niños, mayores o personas con enfermedades crónicas."], "desarrollar": ["Elige una emergencia posible en tu zona y arma una lista de lo que necesitaría una familia: botiquín básico, documentos, agua, ruta al centro de salud más cercano y a quién llamar. Revisa informes públicos de las autoridades para no inventar recomendaciones.", "Mapea qué servicios de salud, farmacias y puntos de reunión hay cerca, señala qué grupos necesitarían más apoyo y entrega una guía de una página con acciones antes, durante y después de la emergencia."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara qué cambiaría la preparación entre una vivienda, una institución educativa y una oficina."}, {"titulo": "Otro formato", "aporta": "haz un simulacro en papel con situaciones ficticias y revisa qué falló."}, {"titulo": "Un paso más", "aporta": "diseña una tarjeta de emergencia familiar con espacio para datos de contacto y necesidades especiales."}], "objetivos": ["Identificar emergencias posibles y su efecto en la salud.", "Armar una lista de preparación basada en fuentes oficiales.", "Ubicar servicios y puntos clave en un mapa.", "Redactar una guía de acción clara."], "habilidades": ["Investigación de fuentes oficiales.", "Mapeo.", "Planificación.", "Redacción clara."], "herramientas": ["Un mapa digital.", "Hoja de cálculo.", "Un editor de documentos."], "lineamientos": ["Basa los consejos en guías de organismos oficiales de gestión de riesgos y salud, y cítalos; no inventes recomendaciones médicas.", "No pidas datos de salud reales: trabaja con familias ficticias o con listas generales."], "otroSector": "Sirve para preparar a una empresa, un colegio, un edificio o un evento ante una emergencia."}$g06sld$::jsonb,13),
('como-influyen-las-areas-verdes-en-como-se-siente-y-se-mueve-la-gente','ciudades',array['salud','ambiente']::text[],'¿Cómo influyen las áreas verdes en cómo se siente y se mueve la gente?','Compara zonas con más y menos áreas verdes y descubre cómo se relacionan con el uso del espacio, la actividad física y el bienestar de las personas.','Análisis','~20 h',20,array['Áreas verdes','Bienestar']::text[],array['investigar','resolver']::text[],'publicos',NULL,'ingenieria ambiental arquitectura ingenieria civil geografia estadistica psicologia medicina ingenieria agroindustrial analisis de mapas. observacion de campo. analisis basico de datos. pensamiento critico. un mapa digital. hoja de calculo. fichas de observacion.',$g07sld${"id": "como-influyen-las-areas-verdes-en-como-se-siente-y-se-mueve-la-gente", "area": "ciudades", "areas2": ["salud", "ambiente"], "titulo": "¿Cómo influyen las áreas verdes en cómo se siente y se mueve la gente?", "resumen": "Compara zonas con más y menos áreas verdes y descubre cómo se relacionan con el uso del espacio, la actividad física y el bienestar de las personas.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Áreas verdes", "Bienestar"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Ingeniería Ambiental", "Arquitectura", "Ingeniería Civil", "Geografía", "Estadística", "Psicología", "Medicina", "Ingeniería Agroindustrial"], "problema": ["Se suele decir que los parques y los árboles hacen bien, pero pocas veces se mira con datos de una zona concreta: cuánta gente los usa, para qué y qué cambia cuando faltan.", "No todas las zonas tienen las mismas áreas verdes, y esa desigualdad casi nunca se ve en un mapa."], "desarrollar": ["Elige dos o tres zonas de una ciudad o de tu centro de estudios y compara cuántas áreas verdes tienen, de qué tamaño y a qué distancia, usando mapas y datos públicos.", "Observa con una ficha cuántas personas usan cada espacio y para qué, y pregunta de forma anónima a unas pocas cómo se sienten allí; cruza todo y concluye qué diferencias aparecen."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "revisa si las zonas con menos áreas verdes también tienen más calor o más ruido."}, {"titulo": "Otro formato", "aporta": "resume tus hallazgos en un mapa de la ciudad con colores por cantidad de áreas verdes."}, {"titulo": "Un paso más", "aporta": "propón dónde y cómo sumar pequeños espacios verdes en una zona con pocos."}], "objetivos": ["Medir cuántas áreas verdes tiene una zona.", "Observar cómo se usan.", "Relacionarlas con el uso y el bienestar con cuidado.", "Proponer dónde sumar más."], "habilidades": ["Análisis de mapas.", "Observación de campo.", "Análisis básico de datos.", "Pensamiento crítico."], "herramientas": ["Un mapa digital.", "Hoja de cálculo.", "Fichas de observación."], "lineamientos": ["Habla de relaciones que observas, no de efectos comprobados: pocas zonas y pocas personas no permiten concluir causas.", "No registres nombres ni fotografíes a personas; trabaja con respuestas anónimas."], "otroSector": "Sirve para analizar cualquier recurso de un barrio: bibliotecas, centros de salud, comercios o transporte."}$g07sld$::jsonb,14),
('como-afecta-la-calidad-del-aire-a-la-vida-diaria-de-una-comunidad','ambiente',array['salud','ciudades']::text[],'¿Cómo afecta la calidad del aire a la vida diaria de una comunidad?','Analiza datos públicos de calidad del aire de una zona y descubre qué días y lugares se ven más afectados, y cómo podría una comunidad informarse y cuidarse mejor.','Análisis','~25 h',25,array['Aire','Salud pública']::text[],array['investigar','resolver']::text[],'publicos',NULL,'ingenieria ambiental estadistica ingenieria quimica ingenieria civil geografia ingenieria de sistemas medicina enfermeria analisis de datos. graficos. lectura de informes tecnicos. comunicacion clara. hoja de calculo. datos de estaciones de monitoreo publicas. una herramienta de graficos.',$g08sld${"id": "como-afecta-la-calidad-del-aire-a-la-vida-diaria-de-una-comunidad", "area": "ambiente", "areas2": ["salud", "ciudades"], "titulo": "¿Cómo afecta la calidad del aire a la vida diaria de una comunidad?", "resumen": "Analiza datos públicos de calidad del aire de una zona y descubre qué días y lugares se ven más afectados, y cómo podría una comunidad informarse y cuidarse mejor.", "tipo": "Análisis", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Aire", "Salud pública"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Ingeniería Ambiental", "Estadística", "Ingeniería Química", "Ingeniería Civil", "Geografía", "Ingeniería de Sistemas", "Medicina", "Enfermería"], "problema": ["La calidad del aire cambia según la hora, el clima y el tráfico, pero la mayoría de personas no sabe cuándo está peor ni qué hacer cuando lo está. Los datos existen, pero suelen estar en tablas difíciles de leer.", "No todas las personas se ven afectadas igual: niños, mayores, quienes trabajan en la calle o quienes viven cerca de vías muy transitadas pueden notarlo más."], "desarrollar": ["Busca datos públicos de una estación de monitoreo cercana, ordénalos por días y horas, y haz gráficos que muestren cuándo el aire está peor y qué lo acompaña, como el clima o el tráfico.", "Con lo que encuentres arma una pequeña guía para la comunidad que explique cómo leer el indicador de calidad del aire y qué precauciones generales recomiendan las autoridades de salud en cada nivel."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara dos zonas distintas de una misma ciudad y busca qué las diferencia."}, {"titulo": "Otro formato", "aporta": "crea un tablero sencillo que muestre el nivel de calidad del aire de la semana en colores."}, {"titulo": "Un paso más", "aporta": "propón cómo avisar a una comunidad cuando el aire está en niveles altos."}], "objetivos": ["Obtener y ordenar datos públicos de calidad del aire.", "Identificar patrones por días y horas.", "Explicar el indicador en palabras claras.", "Preparar una guía de precauciones basada en fuentes oficiales."], "habilidades": ["Análisis de datos.", "Gráficos.", "Lectura de informes técnicos.", "Comunicación clara."], "herramientas": ["Hoja de cálculo.", "Datos de estaciones de monitoreo públicas.", "Una herramienta de gráficos."], "lineamientos": ["Cita las fuentes de los datos y de las recomendaciones; no inventes umbrales ni consejos médicos.", "No relaciones el aire con enfermedades de personas concretas: trabaja con datos de la zona y con información general de salud pública."], "otroSector": "Sirve para analizar el ruido, la temperatura, el agua o cualquier otro indicador público de una zona."}$g08sld$::jsonb,5),
('que-pasa-con-la-salud-de-una-comunidad-cuando-llega-un-fenomeno-climatico','ambiente',array['salud','sociedad']::text[],'¿Qué pasa con la salud de una comunidad cuando llega un fenómeno climático extremo?','Estudia un caso real o inventado de lluvias intensas, sequía, ola de calor o inundación y descubre qué cambia en las necesidades de salud de una comunidad y quién queda más expuesto.','Investigación','~30 h',30,array['Clima','Salud pública']::text[],array['investigar','resolver']::text[],'publicos',NULL,'ingenieria ambiental ingenieria civil geografia estadistica trabajo social enfermeria medicina sociologia investigacion de fuentes. linea de tiempo. analisis de riesgo. redaccion clara. informes publicos de organismos de salud y de gestion de riesgos. hoja de calculo. un mapa o un editor de lineas de tiempo.',$g09sld${"id": "que-pasa-con-la-salud-de-una-comunidad-cuando-llega-un-fenomeno-climatico", "area": "ambiente", "areas2": ["salud", "sociedad"], "titulo": "¿Qué pasa con la salud de una comunidad cuando llega un fenómeno climático extremo?", "resumen": "Estudia un caso real o inventado de lluvias intensas, sequía, ola de calor o inundación y descubre qué cambia en las necesidades de salud de una comunidad y quién queda más expuesto.", "tipo": "Investigación", "tiempo": "~30 h", "horas": 30, "etiquetas": ["Clima", "Salud pública"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Ingeniería Ambiental", "Ingeniería Civil", "Geografía", "Estadística", "Trabajo Social", "Enfermería", "Medicina", "Sociología"], "problema": ["Los fenómenos climáticos extremos se reportan por sus daños en casas y carreteras, y casi siempre se habla poco de lo que pasa con la salud: más enfermedades por el agua o el calor, interrupción de tratamientos, dificultad para llegar a un centro de salud.", "No todas las personas lo viven igual: quienes tienen menos recursos, viven en zonas expuestas o dependen de cuidados suelen ser los más afectados."], "desarrollar": ["Elige un caso documentado en informes públicos o inventa uno realista y arma una línea de tiempo con lo que pasó antes, durante y después del fenómeno, señalando qué servicios o personas quedaron más expuestos.", "Resume cómo cambiaron las necesidades de salud y propón tres acciones que una comunidad podría hacer para estar mejor preparada, apoyándote en recomendaciones oficiales."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara dos casos distintos, como una inundación y una ola de calor, y busca qué se repite."}, {"titulo": "Otro formato", "aporta": "resume el caso en un mapa de la zona con los lugares y grupos más afectados."}, {"titulo": "Un paso más", "aporta": "diseña un aviso temprano sencillo para que una comunidad sepa qué hacer antes del evento."}], "objetivos": ["Reconstruir un caso con fuentes públicas o ficticio.", "Identificar efectos en servicios y grupos de personas.", "Reconocer quién queda más expuesto y por qué.", "Proponer acciones de preparación."], "habilidades": ["Investigación de fuentes.", "Línea de tiempo.", "Análisis de riesgo.", "Redacción clara."], "herramientas": ["Informes públicos de organismos de salud y de gestión de riesgos.", "Hoja de cálculo.", "Un mapa o un editor de líneas de tiempo."], "lineamientos": ["Cita siempre tus fuentes y distingue lo que está documentado de lo que tú supones.", "Si usas un caso real, no incluyas nombres ni datos de personas afectadas ni fotos de víctimas."], "otroSector": "El mismo análisis sirve para estudiar cómo afecta un evento al transporte, a las escuelas, a un negocio o a una cadena de suministro."}$g09sld$::jsonb,6),
('una-guia-para-cuidarse-del-calor-o-del-frio-intenso','ambiente',array['salud','arte']::text[],'Una guía para cuidarse del calor o del frío intenso','Prepara una guía clara y fácil de compartir para que una familia o una comunidad sepa cómo prepararse y qué hacer cuando llega una ola de calor o de frío.','Guía','~15 h',15,array['Calor y frío','Prevención']::text[],array['crear','resolver']::text[],'publicos',NULL,'ingenieria ambiental diseno grafico comunicaciones enfermeria medicina trabajo social educacion publicidad comunicacion clara. diseno de informacion. lectura critica de fuentes. trabajo con usuarios. un editor de afiches o de presentaciones. guias oficiales de organismos de salud. un formulario simple para probar con lectores.',$g10sld${"id": "una-guia-para-cuidarse-del-calor-o-del-frio-intenso", "area": "ambiente", "areas2": ["salud", "arte"], "titulo": "Una guía para cuidarse del calor o del frío intenso", "resumen": "Prepara una guía clara y fácil de compartir para que una familia o una comunidad sepa cómo prepararse y qué hacer cuando llega una ola de calor o de frío.", "tipo": "Guía", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Calor y frío", "Prevención"], "intencion": ["crear", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Ingeniería Ambiental", "Diseño Gráfico", "Comunicaciones", "Enfermería", "Medicina", "Trabajo Social", "Educación", "Publicidad"], "problema": ["Las olas de calor y de frío se anuncian en los noticieros, pero casi nunca se explica con claridad qué hacer en casa, en el colegio o en el trabajo. Las recomendaciones están en documentos largos o técnicos.", "Algunas personas tienen más riesgo: bebés, mayores, quienes trabajan al aire libre o viven en viviendas muy expuestas. Una guía mal hecha no les llega."], "desarrollar": ["Revisa recomendaciones de organismos oficiales de salud y de gestión de riesgos, quédate con las que se repiten y reescríbelas en frases cortas, ordenadas en antes, durante y después del evento.", "Diseña una versión en una hoja o en un afiche, pide a dos personas que no sean de tu carrera que la lean y te digan qué no entendieron, y ajústala."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "adapta la guía para un público específico, como niños, adultos mayores o trabajadores de calle."}, {"titulo": "Otro formato", "aporta": "conviértela en una serie de imágenes cortas para compartir por mensajería."}, {"titulo": "Un paso más", "aporta": "prepara una versión para una institución, con un plan de acción para el día del evento."}], "objetivos": ["Reunir recomendaciones de fuentes oficiales.", "Reescribirlas en lenguaje sencillo.", "Diseñar una versión visual clara.", "Probarla con lectores y mejorarla."], "habilidades": ["Comunicación clara.", "Diseño de información.", "Lectura crítica de fuentes.", "Trabajo con usuarios."], "herramientas": ["Un editor de afiches o de presentaciones.", "Guías oficiales de organismos de salud.", "Un formulario simple para probar con lectores."], "lineamientos": ["No des indicaciones de tratamiento ni dosis: limítate a prevención y a cuándo buscar atención, según fuentes oficiales, y cítalas.", "Aclara que la guía es informativa y que ante síntomas graves se debe acudir a un servicio de salud."], "otroSector": "La misma guía sirve para otros eventos, como incendios, lluvias fuertes, humo o cortes prolongados de energía."}$g10sld$::jsonb,7),
('que-influye-en-lo-que-come-una-comunidad','agricultura',array['salud','sociedad']::text[],'¿Qué influye en lo que come una comunidad?','Descubre qué factores, como el precio, la distancia, el tiempo o la costumbre, hacen que una comunidad coma como come, y qué podría facilitar una alimentación más variada.','Investigación','~25 h',25,array['Alimentación','Comunidad']::text[],array['investigar','resolver']::text[],'publicos',NULL,'nutricion ingenieria agroindustrial sociologia trabajo social economia estadistica medicina ingenieria ambiental investigacion de campo. analisis basico de datos. mapeo. pensamiento critico. hoja de calculo. un mapa digital. informes publicos de alimentacion y precios.',$g11sld${"id": "que-influye-en-lo-que-come-una-comunidad", "area": "agricultura", "areas2": ["salud", "sociedad"], "titulo": "¿Qué influye en lo que come una comunidad?", "resumen": "Descubre qué factores, como el precio, la distancia, el tiempo o la costumbre, hacen que una comunidad coma como come, y qué podría facilitar una alimentación más variada.", "tipo": "Investigación", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Alimentación", "Comunidad"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Nutrición", "Ingeniería Agroindustrial", "Sociología", "Trabajo Social", "Economía", "Estadística", "Medicina", "Ingeniería Ambiental"], "problema": ["La alimentación de una comunidad no depende solo de lo que cada persona decide: influye qué se vende cerca, cuánto cuesta, cuánto tiempo hay para cocinar y qué se acostumbra. Rara vez se ve el conjunto.", "Dos barrios de la misma ciudad pueden comer muy distinto, y el motivo no siempre es de gusto: a veces simplemente no hay otra opción."], "desarrollar": ["Elige una comunidad o zona y reúne, con datos públicos y con una mirada de campo, qué alimentos se consiguen, dónde, a qué precio y a qué distancia, y cómo es el tiempo disponible en el día.", "Resume los factores que más influyen en una lista ordenada y propón tres ideas para facilitar el acceso a una alimentación más variada, como mercados cercanos, ferias o cocinas compartidas."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara dos zonas y busca qué factor explica más la diferencia."}, {"titulo": "Otro formato", "aporta": "haz un mapa de dónde se consiguen alimentos frescos y dónde no."}, {"titulo": "Un paso más", "aporta": "estima cuánto costaría una semana de comidas variadas en cada zona."}], "objetivos": ["Identificar factores que influyen en la alimentación.", "Reunir datos de precios, distancias y disponibilidad.", "Compararlos entre zonas.", "Proponer ideas para mejorar el acceso."], "habilidades": ["Investigación de campo.", "Análisis básico de datos.", "Mapeo.", "Pensamiento crítico."], "herramientas": ["Hoja de cálculo.", "Un mapa digital.", "Informes públicos de alimentación y precios."], "lineamientos": ["No evalúes ni juzgues lo que come cada persona: el análisis es de la comunidad y sus condiciones, no de individuos.", "No des consejos dietéticos personales: usa solo guías públicas de organismos de salud o nutrición."], "otroSector": "El mismo método sirve para analizar el acceso a medicamentos, transporte, internet o cualquier servicio básico."}$g11sld$::jsonb,3),
('que-tan-saludable-es-lo-que-se-vende-cerca-de-tu-centro-de-estudios','agricultura',array['salud','negocios']::text[],'¿Qué tan saludable es lo que se vende cerca de tu centro de estudios?','Revisa qué alimentos y bebidas se ofrecen a estudiantes cerca de tu centro de estudios, compáralos con guías públicas y descubre cómo influye la oferta en la forma de comer durante la jornada.','Análisis','~20 h',20,array['Alimentación','Entorno']::text[],array['investigar','resolver']::text[],'propios',NULL,'nutricion ingenieria agroindustrial administracion estadistica ingenieria industrial medicina trabajo social economia observacion de campo. clasificacion de datos. analisis basico. comunicacion. hoja de calculo. un mapa digital. guias publicas de alimentacion.',$g12sld${"id": "que-tan-saludable-es-lo-que-se-vende-cerca-de-tu-centro-de-estudios", "area": "agricultura", "areas2": ["salud", "negocios"], "titulo": "¿Qué tan saludable es lo que se vende cerca de tu centro de estudios?", "resumen": "Revisa qué alimentos y bebidas se ofrecen a estudiantes cerca de tu centro de estudios, compáralos con guías públicas y descubre cómo influye la oferta en la forma de comer durante la jornada.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Alimentación", "Entorno"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "propios: puedes usar tus propias mediciones y las de personas cercanas que acepten participar, sin datos médicos ni diagnósticos.", "carreras": ["Nutrición", "Ingeniería Agroindustrial", "Administración", "Estadística", "Ingeniería Industrial", "Medicina", "Trabajo Social", "Economía"], "problema": ["Quienes estudian muchas horas comen con prisa y con lo que tienen a mano. La oferta cercana pesa más de lo que parece, pero casi nadie la ha revisado ni sabe qué tan variada o saludable es.", "Elegir mejor también depende del precio, del tiempo y de la información, no solo de la voluntad."], "desarrollar": ["Recorre los alrededores de tu centro de estudios y anota qué se vende, a qué precio y en qué cantidad, usando una lista sencilla de categorías, como frutas, comidas completas, fritos, dulces y bebidas azucaradas.", "Compara lo que encuentres con una guía pública de alimentación, resume cuánto de la oferta cubre opciones variadas y propón dos o tres mejoras posibles para quienes venden y para quienes compran."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "pregunta de forma anónima a algunos estudiantes qué compran y por qué, y compara con la oferta."}, {"titulo": "Otro formato", "aporta": "haz un mapa de la zona con colores por tipo de oferta."}, {"titulo": "Un paso más", "aporta": "diseña una «ruta de almuerzo variado» con precios y tiempos para quienes tienen poco rato."}], "objetivos": ["Registrar la oferta de alimentos de una zona.", "Clasificarla con criterios claros.", "Compararla con guías públicas.", "Proponer mejoras realistas."], "habilidades": ["Observación de campo.", "Clasificación de datos.", "Análisis básico.", "Comunicación."], "herramientas": ["Hoja de cálculo.", "Un mapa digital.", "Guías públicas de alimentación."], "lineamientos": ["Evita señalar o criticar negocios por su nombre en tu informe; habla de categorías y de la zona en general.", "No des planes de dieta ni juzgues lo que come cada persona: trabaja con la oferta, no con las personas."], "otroSector": "El mismo análisis sirve para revisar la oferta de cafeterías, kioscos, máquinas expendedoras o comedores de una empresa o un hospital."}$g12sld$::jsonb,4)
